import { navigate } from "gatsby";
import React, { useEffect, useState } from "react";
import type { UserProfile, UserStatus } from "../types";
import { listUsers, setUserStatus } from "../../../sessionServices/users/usersService";
import { useAuth } from "../../auth/AuthContext";

const STATUS_BADGE: Record<UserStatus, string> = {
  active: "bg-green-100 text-green-700",
  inactive: "bg-gray-100 text-gray-600",
  blocked: "bg-red-100 text-red-700",
};

const ROLE_BADGE: Record<string, string> = {
  admin: "bg-purple-100 text-purple-700",
  agent: "bg-blue-100 text-blue-700",
  customer: "bg-orange-100 text-orange-700",
};

export function UserList() {
  const { user } = useAuth();
  const [users, setUsers] = useState<UserProfile[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadUsers();
  }, []);

  async function loadUsers() {
    setLoading(true);
    setError(null);
    try {
      const data = await listUsers();
      setUsers(data);
    } catch {
      setError("Failed to load users.");
    } finally {
      setLoading(false);
    }
  }

  async function handleStatusToggle(target: UserProfile) {
    if (!user) return;
    const nextStatus: UserStatus =
      target.status === "active" ? "blocked" : "active";
    try {
      await setUserStatus(target.uid, nextStatus, user.uid);
      setUsers((prev) =>
        prev.map((u) =>
          u.uid === target.uid ? { ...u, status: nextStatus } : u
        )
      );
    } catch {
      alert("Could not update user status. Try again.");
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-lg bg-red-50 px-4 py-3 text-sm text-red-600">
        {error}
      </div>
    );
  }

  if (users.length === 0) {
    return (
      <div className="rounded-xl bg-white py-12 text-center ring-1 ring-gray-200">
        <p className="text-sm text-gray-500">No users yet.</p>
      </div>
    );
  }

  return (
    <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
      <table className="min-w-full divide-y divide-gray-100">
        <thead>
          <tr className="bg-gray-50">
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Name</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Email</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Role</th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase tracking-wide text-gray-500">Status</th>
            <th className="px-4 py-3" />
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-100">
          {users.map((u) => (
            <tr key={u.uid} className="hover:bg-gray-50">
              <td className="px-4 py-3 text-sm font-medium text-gray-900">{u.fullName}</td>
              <td className="px-4 py-3 text-sm text-gray-600">{u.email}</td>
              <td className="px-4 py-3">
                <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${ROLE_BADGE[u.role] ?? "bg-gray-100 text-gray-600"}`}>
                  {u.role}
                </span>
              </td>
              <td className="px-4 py-3">
                <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_BADGE[u.status]}`}>
                  {u.status}
                </span>
              </td>
              <td className="px-4 py-3 text-right">
                <button
                  onClick={() => navigate(`/admin/users/${u.uid}`)}
                  className="mr-2 text-xs text-gray-500 underline hover:text-gray-900"
                >
                  Edit
                </button>
                <button
                  onClick={() => handleStatusToggle(u)}
                  className={`text-xs underline ${
                    u.status === "active"
                      ? "text-red-500 hover:text-red-700"
                      : "text-green-600 hover:text-green-800"
                  }`}
                >
                  {u.status === "active" ? "Block" : "Activate"}
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
